const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Artiklar</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Den tyska artikeln stämmer inte alltid överens med ordets genus på svenska (en/ett). Därför är det bäst att lära sig substantiv tillsammans med artikeln.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exempel på artiklar</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — bord</div>\n      <div class=\"kurss-example\">die Tür — dörr</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">das Mädchen — flicka</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Ofta DER</h4>\n    <p class=\"artikuli-explain\">DER används ofta för manliga personer, dagar, månader, årstider och vissa ord med bestämda ändelser.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → ofta DER, till exempel: der Computer, der Lehrer <span class=\"artikuli-note\">men inte alltid</span></div>\n      <div class=\"kurss-example\">-ling → ofta DER, till exempel: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → ofta DER, till exempel: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">manliga personer → der Mann, der Vater</div>\n      <div class=\"kurss-example\">yrken → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">bilmärken → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">dagar → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">månader → der August, der Dezember</div>\n      <div class=\"kurss-example\">årstider → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exempel</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — man</div>\n      <div class=\"kurss-example\">der Vater — far / pappa</div>\n      <div class=\"kurss-example\">der Montag — måndag</div>\n      <div class=\"kurss-example\">der August — augusti</div>\n      <div class=\"kurss-example\">der Sommer — sommar</div>\n      <div class=\"kurss-example\">der Lehrer — lärare</div>\n      <div class=\"kurss-example\">der Computer — dator</div>\n      <div class=\"kurss-example\">der Schmetterling — fjäril</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Ofta DIE</h4>\n    <p class=\"artikuli-explain\">DIE används ofta för kvinnliga personer, plural och ord med ändelserna -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">kvinnliga personer → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">motorcykelmärken → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plural → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">plural nästan alltid → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exempel</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — kvinna</div>\n      <div class=\"kurss-example\">die Mutter — mor / mamma</div>\n      <div class=\"kurss-example\">die Wohnung — lägenhet</div>\n      <div class=\"kurss-example\">die Rechnung — räkning / faktura</div>\n      <div class=\"kurss-example\">die Freiheit — frihet</div>\n      <div class=\"kurss-example\">die Möglichkeit — möjlighet</div>\n      <div class=\"kurss-example\">die Mannschaft — lag</div>\n      <div class=\"kurss-example\">die Nation — nation</div>\n      <div class=\"kurss-example\">die Universität — universitet</div>\n      <div class=\"kurss-example\">die Polizei — polis</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Ofta DAS</h4>\n    <p class=\"artikuli-explain\">DAS används ofta för diminutiv på -chen / -lein, många ord på -ment / -um och verb som substantiv.</p>\n\n    <h5 class=\"artikuli-subtitle\">Regler</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metaller → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">kemiska grundämnen → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hotell → das Hotel</div>\n      <div class=\"kurss-example\">färger som substantiv → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verb som substantiv → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verb som substantiv → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exempel</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — barn</div>\n      <div class=\"kurss-example\">das Mädchen — flicka</div>\n      <div class=\"kurss-example\">das Häuschen — litet hus / stuga</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centrum</div>\n      <div class=\"kurss-example\">das Museum — museum</div>\n      <div class=\"kurss-example\">das Essen — ätande / mat</div>\n      <div class=\"kurss-example\">das Lernen — inlärning</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Viktiga undantag / lär dig med artikeln</h4>\n    <p class=\"artikuli-explain\">För vissa ord går det inte att säkert avgöra artikeln utifrån ändelsen eller ordets genus på svenska. Dem är det bäst att lära sig tillsammans med artikeln.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — dörr</div>\n      <div class=\"kurss-example\">das Messer — kniv</div>\n      <div class=\"kurss-example\">die Sonne — sol</div>\n      <div class=\"kurss-example\">der Mond — måne</div>\n      <div class=\"kurss-example\">das Mädchen — flicka</div>\n      <div class=\"kurss-example\">das Auto — bil</div>\n      <div class=\"kurss-example\">der Käse — ost</div>\n      <div class=\"kurss-example\">die Gabel — gaffel</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Ändelser och ordgrupper hjälper dig att gissa artikeln, men de är ingen 100% säker regel. Om du är osäker, lär dig ordet tillsammans med artikeln.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronomen</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ och Dativ — pronomenformer.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — vem/vad?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — jag</div><div class=\"kurss-example\">du — du</div><div class=\"kurss-example\">er — han</div><div class=\"kurss-example\">sie — hon</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">wir — vi</div><div class=\"kurss-example\">ihr — ni</div><div class=\"kurss-example\">sie — de</div><div class=\"kurss-example\">Sie — Ni (artigt tilltal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — vem/vad?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — mig</div><div class=\"kurss-example\">dich — dig</div><div class=\"kurss-example\">ihn — honom (m.)</div><div class=\"kurss-example\">sie — henne (f.)</div><div class=\"kurss-example\">es — det</div><div class=\"kurss-example\">uns — oss</div><div class=\"kurss-example\">euch — er</div><div class=\"kurss-example\">sie — dem</div><div class=\"kurss-example\">Sie — Er (artigt tilltal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — till vem?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — (till) mig</div><div class=\"kurss-example\">dir — (till) dig</div><div class=\"kurss-example\">ihm — (till) honom / det</div><div class=\"kurss-example\">ihr — (till) henne</div><div class=\"kurss-example\">uns — (till) oss</div><div class=\"kurss-example\">euch — (till) er</div><div class=\"kurss-example\">ihnen — (till) dem</div><div class=\"kurss-example\">Ihnen — (till) Er (artigt tilltal)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Hur väljer man form?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subjekt (vem gör något?)</li><li><span class=\"case-red\">Akkusativ</span> — direkt objekt (vem/vad?)</li><li><span class=\"case-green\">Dativ</span> — indirekt objekt (till vem?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exempel</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Jag ser dig.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Jag ser honom.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Vi tycker om er.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Jag hjälper dig.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Jag ger honom en bok.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vi tackar er.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ är alltid satsens subjekt, medan Akkusativ och Dativ är objekt. Titta på verbet och fråga: <span class=\"case-red\">vem/vad?</span> eller <span class=\"case-green\">till vem?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vokaler — långa och korta</h3>\n            <p class=\"kurss-lesson-intro\">På tyska kan vokaler vara långa eller korta. Det påverkar hur ordet uttalas.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Lång vokal</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — varm</div><div class=\"kurss-example\">gut (goot) — bra</div><div class=\"kurss-example\">Tat (taat) — gärning / handling</div><div class=\"kurss-example\">Flur (floor) — hall / korridor</div><div class=\"kurss-example\">Weg (veek) — väg</div><div class=\"kurss-example\">Hut (hoot) — hatt</div><div class=\"kurss-example\">Hof (hååf) — gård</div><div class=\"kurss-example\">Schlaf (sjlaaf) — sömn</div></div>\n              <p>Om vokalen följs av en enda konsonant uttalas den ofta lång.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Kort vokal</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilts) — svamp</div><div class=\"kurss-example\">Wort (vårt) — ord</div><div class=\"kurss-example\">Mund (mont) — mun</div><div class=\"kurss-example\">bald (balt) — snart</div><div class=\"kurss-example\">scharf (sjarf) — skarp</div><div class=\"kurss-example\">Feld (fält) — fält</div><div class=\"kurss-example\">voll (fåll) — full</div></div>\n              <p>Om vokalen följs av två eller flera konsonanter uttalas den ofta kort.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ändelserna en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zingen) — sjunga</div><div class=\"kurss-example\">tragen (traagen) — bära</div><div class=\"kurss-example\">Garten (garten) — trädgård</div><div class=\"kurss-example\">Vogel (fåågel) — fågel</div><div class=\"kurss-example\">Segel (zeegel) — segel</div><div class=\"kurss-example\">Braten (braaten) — stek</div><div class=\"kurss-example\">Bogen (båågen) — båge</div><div class=\"kurss-example\">Spiegel (sjpiigel) — spegel</div><div class=\"kurss-example\">Finger (finger) — finger</div><div class=\"kurss-example\">Halter (halter) — hållare</div><div class=\"kurss-example\">Arbeiter (arbajter) — arbetare</div><div class=\"kurss-example\">Häuser (håjzer) — hus (plural)</div><div class=\"kurss-example\">wieder (viider) — igen</div><div class=\"kurss-example\">breiter (brajter) — bredare</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Bokstaven h som längdtecken</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (raamen) — ram</div><div class=\"kurss-example\">Ohr (åår) — öra</div><div class=\"kurss-example\">Kohle (kååle) — kol</div><div class=\"kurss-example\">Zahl (tsaal) — tal / siffra</div><div class=\"kurss-example\">ihn (iin) — honom</div><div class=\"kurss-example\">ihm (iim) — (åt) honom</div><div class=\"kurss-example\">Huhn (hoon) — höna</div><div class=\"kurss-example\">nahm (naam) — tog</div><div class=\"kurss-example\">nehmen (neemen) — ta</div><div class=\"kurss-example\">Schuh (sjoo) — sko</div></div>\n              <p>I vissa ord förlänger h den föregående vokalen. I sådana fall uttalas h oftast inte.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Ändelser på e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampa</div><div class=\"kurss-example\">Hase (haaze) — hare</div><div class=\"kurss-example\">Knabe (knaabe) — pojke</div><div class=\"kurss-example\">Rabe (raabe) — korp</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Långt i = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dii) — artikeln ”die”</div><div class=\"kurss-example\">diese (diize) — denna / dessa</div><div class=\"kurss-example\">wieder (viider) — igen</div><div class=\"kurss-example\">Fliege (fliige) — fluga</div><div class=\"kurss-example\">Ziege (tsiige) — get</div><div class=\"kurss-example\">Stiel (sjtiil) — skaft / stjälk</div><div class=\"kurss-example\">Dieb (diip) — tjuv</div><div class=\"kurss-example\">hier (hiir) — här</div></div>\n              <p>Långt i skrivs på tyska ofta som ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Dubbla vokaler</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zaal) — sal</div><div class=\"kurss-example\">Saat (zaat) — sådd / utsäde</div><div class=\"kurss-example\">Staat (sjtaat) — stat</div><div class=\"kurss-example\">Beere (beere) — bär</div><div class=\"kurss-example\">See (zee) — sjö / hav</div><div class=\"kurss-example\">Beet (beet) — rabatt / odlingsbädd</div><div class=\"kurss-example\">Boot (bååt) — båt</div><div class=\"kurss-example\">Moor (måår) — myr / mosse</div><div class=\"kurss-example\">Moos (måås) — mossa</div></div>\n              <p>Dubbla vokaler uttalas oftast långa.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — vägg</div><div class=\"kurss-example\">Wände (vände) — väggar</div><div class=\"kurss-example\">Vater (faater) — far</div><div class=\"kurss-example\">Väter (fääter) — fäder</div><div class=\"kurss-example\">Schrank (sjrank) — skåp</div><div class=\"kurss-example\">Schränke (sjränke) — skåp (plural)</div><div class=\"kurss-example\">Bank (bank) — bänk / bank</div><div class=\"kurss-example\">Bänke (bänke) — bänkar</div><div class=\"kurss-example\">Tal (taal) — dal</div><div class=\"kurss-example\">Täler (tääler) — dalar</div></div>\n              <p>ä är omljudet av a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rååze) — ros</div><div class=\"kurss-example\">Röschen (röös-chen) — liten ros</div><div class=\"kurss-example\">Ofen (ååfen) — ugn</div><div class=\"kurss-example\">Öfen (ööfen) — ugnar</div><div class=\"kurss-example\">Rock (råck) — kjol</div><div class=\"kurss-example\">Röcke (röcke) — kjolar</div></div>\n              <p>ö är omljudet av o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (korts) — kort</div><div class=\"kurss-example\">kürzer (kyrtser) — kortare</div><div class=\"kurss-example\">Kunst (konst) — konst</div><div class=\"kurss-example\">Künste (kynste) — konster</div><div class=\"kurss-example\">Mutter (motter) — mor</div><div class=\"kurss-example\">Mütter (mytter) — mödrar</div></div>\n              <p>ü är omljudet av u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — träd</div><div class=\"kurss-example\">Bäume (båjme) — träd (plural)</div><div class=\"kurss-example\">Haus (haus) — hus</div><div class=\"kurss-example\">Häuser (håjzer) — hus (plural)</div><div class=\"kurss-example\">Strauch (sjtrauch) — buske</div><div class=\"kurss-example\">Sträucher (sjtråjcher) — buskar</div><div class=\"kurss-example\">Maus (maus) — mus</div><div class=\"kurss-example\">Mäuse (måjze) — möss</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (håjte) — i dag</div><div class=\"kurss-example\">Leute (låjte) — människor / folk</div><div class=\"kurss-example\">neu (nåj) — ny</div><div class=\"kurss-example\">neun (nåjn) — nio</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftonger: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (majn) — min</div><div class=\"kurss-example\">dein (dajn) — din</div><div class=\"kurss-example\">sein (zajn) — hans / dess / vara</div><div class=\"kurss-example\">frei (fraj) — fri</div><div class=\"kurss-example\">arbeiten (arbajten) — arbeta</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Uttalsanteckningar till lektion 2</h4>\n              <ul class=\"kurss-summary-list\"><li>i orden ich, nicht, rechnen, zeichnen uttalas ”ch” mjukt (nära svenskt tj-ljud som i ”tjugo”)</li><li>i orden arbeiten och zeichnen uttalas ”ei” som ”aj”</li><li>”sp” i början av ett ord uttalas som ”sjp”</li><li>i verbet tun uttalas bokstaven ”u” långt (som svenskt långt o i ”sko”)</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sammanfattning</h4>\n              <ul class=\"kurss-summary-list\"><li>en konsonant efter vokalen → ofta lång vokal</li><li>två eller flera konsonanter → ofta kort vokal</li><li>h kan förlänga vokalen</li><li>ie betyder ofta långt i</li><li>dubbla vokaler är oftast långa</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Konsonanter och bokstavskombinationer</h3>\n            <p class=\"kurss-lesson-intro\">På tyska uttalas vissa konsonanter och bokstavskombinationer annorlunda än de skrivs. I den här lektionen finns de viktigaste exemplen för nybörjare.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Konsonanter</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (raat) — hjul</div><div class=\"kurss-example\">die Räder (rääder) — hjul (plural)</div><div class=\"kurss-example\">Bad (baat) — bad / badrum</div><div class=\"kurss-example\">Bäder (bääder) — bad (plural)</div></div>\n              <p>I slutet av ett ord uttalas konsonanter ofta inte så som de skrivs.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>”ch” kan uttalas mjukt eller hårt. I vissa ord låter det nästan som svenskt tj-ljud (som i ”tjugo”), i andra som ett hest ljud långt bak i halsen, närmare ”k”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rechnen) — räkna</div><div class=\"kurss-example\">zeichnen (tsajchnen) — rita</div><div class=\"kurss-example\">nicht (nicht) — inte</div><div class=\"kurss-example\">schlecht (sjlecht) — dålig</div><div class=\"kurss-example\">mich (mich) — mig</div><div class=\"kurss-example\">dich (dich) — dig</div><div class=\"kurss-example\">Strauch (sjtrauch) — buske</div><div class=\"kurss-example\">noch (nåch) — ännu / fortfarande</div><div class=\"kurss-example\">Nacht (nacht) — natt</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>”sch” uttalas på tyska som svenskt sj-ljud (som i ”dusch”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (sjoole) — skola</div><div class=\"kurss-example\">Schüler (sjyyler) — elev</div><div class=\"kurss-example\">Schiff (sjiff) — fartyg / skepp</div><div class=\"kurss-example\">Schraube (sjraube) — skruv</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp och st i början av ett ord</h4>\n              <p>I början av ett ord eller en stavelse uttalas ”sp” ofta som ”sjp” och ”st” som ”sjt”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (sjpiilen) — spela / leka</div><div class=\"kurss-example\">Sprung (sjprong) — hopp / språng</div><div class=\"kurss-example\">stehen (sjtee-en) — stå</div><div class=\"kurss-example\">Stall (sjtall) — stall / ladugård</div><div class=\"kurss-example\">Stand (sjtant) — läge / stånd</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>”qu” uttalas på tyska oftast som ”kv”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (kvaal) — plåga / kval</div><div class=\"kurss-example\">Quartier (kvartiir) — kvarter / logi</div><div class=\"kurss-example\">quer (kveer) — tvärs</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s och z</h4>\n              <p>I början av ett ord låter ”s” ofta som ett tonande s (som engelskt ”z” i ”zoo”) – i uttalsangivelserna skrivet ”z”. Bokstaven ”z” uttalas på tyska som ”ts”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zaagen) — säga</div><div class=\"kurss-example\">singen (zingen) — sjunga</div><div class=\"kurss-example\">Rose (rååze) — ros</div><div class=\"kurss-example\">Zahl (tsaal) — tal / siffra</div><div class=\"kurss-example\">Zeit (tsajt) — tid</div><div class=\"kurss-example\">Zink (tsink) — zink</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>På tyska uttalas ”v” ofta som ”f”. I lånord låter det ofta som svenskt ”v”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (faater) — far</div><div class=\"kurss-example\">von (fån) — från / av</div><div class=\"kurss-example\">viel (fiil) — mycket</div><div class=\"kurss-example\">vier (fiir) — fyra</div><div class=\"kurss-example\">Villa (villa) — villa</div><div class=\"kurss-example\">Klavier (klaviir) — piano</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x och y</h4>\n              <p>”x” uttalas som ”ks”. ”y” uttalas i vissa ord som ”ü” (som svenskt ”y”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (feeliks) — Felix</div><div class=\"kurss-example\">Axt (akst) — yxa</div><div class=\"kurss-example\">Mystik (mystik) — mystik</div><div class=\"kurss-example\">Mythe (myyte) — myt</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>”ß” uttalas på tyska som ”s”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (foos) — fot</div><div class=\"kurss-example\">Füße (fyyse) — fötter</div><div class=\"kurss-example\">Grüße (gryyse) — hälsningar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Sammanfattning</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → sj</li><li>sp / st i början → sjp / sjt</li><li>qu → kv</li><li>z → ts</li><li>v ofta → f</li><li>x → ks</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Grunderna i verb</h3>\n            <p class=\"kurss-lesson-intro\">Verb i lektion 1 och deras former (konjugation)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verb</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — att komma</div><div class=\"kurss-example\">gehen — att gå</div><div class=\"kurss-example\">stehen — att stå</div><div class=\"kurss-example\">singen — att sjunga</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — jag kommer</div><div class=\"kurss-example\">du kommst — du kommer</div><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hon kommer</div><div class=\"kurss-example\">wir kommen — vi kommer</div><div class=\"kurss-example\">ihr kommt — ni kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — jag går</div><div class=\"kurss-example\">du gehst — du går</div><div class=\"kurss-example\">er geht — han går</div><div class=\"kurss-example\">sie geht — hon går</div><div class=\"kurss-example\">wir gehen — vi går</div><div class=\"kurss-example\">ihr geht — ni går</div><div class=\"kurss-example\">sie gehen — de går</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — jag står</div><div class=\"kurss-example\">du stehst — du står</div><div class=\"kurss-example\">er steht — han står</div><div class=\"kurss-example\">sie steht — hon står</div><div class=\"kurss-example\">wir stehen — vi står</div><div class=\"kurss-example\">ihr steht — ni står</div><div class=\"kurss-example\">sie stehen — de står</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — jag sjunger</div><div class=\"kurss-example\">du singst — du sjunger</div><div class=\"kurss-example\">er singt — han sjunger</div><div class=\"kurss-example\">sie singt — hon sjunger</div><div class=\"kurss-example\">wir singen — vi sjunger</div><div class=\"kurss-example\">ihr singt — ni sjunger</div><div class=\"kurss-example\">sie singen — de sjunger</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verb i lektion 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — att spela</div><div class=\"kurss-example\">arbeiten — att arbeta</div><div class=\"kurss-example\">fragen — att fråga</div><div class=\"kurss-example\">antworten — att svara</div><div class=\"kurss-example\">rechnen — att räkna</div><div class=\"kurss-example\">zeichnen — att rita</div><div class=\"kurss-example\">tun — att göra</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — jag spelar</div><div class=\"kurss-example\">du spielst — du spelar</div><div class=\"kurss-example\">er spielt — han spelar</div><div class=\"kurss-example\">sie spielt — hon spelar</div><div class=\"kurss-example\">wir spielen — vi spelar</div><div class=\"kurss-example\">ihr spielt — ni spelar</div><div class=\"kurss-example\">sie spielen — de spelar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — jag arbetar</div><div class=\"kurss-example\">du arbeitest — du arbetar</div><div class=\"kurss-example\">er arbeitet — han arbetar</div><div class=\"kurss-example\">sie arbeitet — hon arbetar</div><div class=\"kurss-example\">wir arbeiten — vi arbetar</div><div class=\"kurss-example\">ihr arbeitet — ni arbetar</div><div class=\"kurss-example\">sie arbeiten — de arbetar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — jag frågar</div><div class=\"kurss-example\">du fragst — du frågar</div><div class=\"kurss-example\">er fragt — han frågar</div><div class=\"kurss-example\">sie fragt — hon frågar</div><div class=\"kurss-example\">wir fragen — vi frågar</div><div class=\"kurss-example\">ihr fragt — ni frågar</div><div class=\"kurss-example\">sie fragen — de frågar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — jag svarar</div><div class=\"kurss-example\">du antwortest — du svarar</div><div class=\"kurss-example\">er antwortet — han svarar</div><div class=\"kurss-example\">sie antwortet — hon svarar</div><div class=\"kurss-example\">wir antworten — vi svarar</div><div class=\"kurss-example\">ihr antwortet — ni svarar</div><div class=\"kurss-example\">sie antworten — de svarar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — jag räknar</div><div class=\"kurss-example\">du rechnest — du räknar</div><div class=\"kurss-example\">er rechnet — han räknar</div><div class=\"kurss-example\">sie rechnet — hon räknar</div><div class=\"kurss-example\">wir rechnen — vi räknar</div><div class=\"kurss-example\">ihr rechnet — ni räknar</div><div class=\"kurss-example\">sie rechnen — de räknar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — jag ritar</div><div class=\"kurss-example\">du zeichnest — du ritar</div><div class=\"kurss-example\">er zeichnet — han ritar</div><div class=\"kurss-example\">sie zeichnet — hon ritar</div><div class=\"kurss-example\">wir zeichnen — vi ritar</div><div class=\"kurss-example\">ihr zeichnet — ni ritar</div><div class=\"kurss-example\">sie zeichnen — de ritar</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — jag gör</div><div class=\"kurss-example\">du tust — du gör</div><div class=\"kurss-example\">er tut — han gör</div><div class=\"kurss-example\">sie tut — hon gör</div><div class=\"kurss-example\">wir tun — vi gör</div><div class=\"kurss-example\">ihr tut — ni gör</div><div class=\"kurss-example\">sie tun — de gör</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Meningsbyggnad</h3>\n            <p class=\"kurss-lesson-intro\">I en frågesats står verbet på tyska vanligtvis på första plats.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Exempel</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Du kommer.</div><div class=\"kurss-example\">Kommst du? — Kommer du?</div><div class=\"kurss-example\">Er singt. — Han sjunger.</div><div class=\"kurss-example\">Singt er? — Sjunger han?</div><div class=\"kurss-example\">Stehst du? — Står du?</div><div class=\"kurss-example\">Ja, ich stehe. — Ja, jag står.</div><div class=\"kurss-example\">Geht ihr? — Går ni?</div><div class=\"kurss-example\">Ja, wir gehen. — Ja, vi går.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Frågor med ”was”</h4>\n              <p>Om frågan börjar med ett frågeord står verbet på tyska vanligtvis direkt efter frågeordet.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Vad gör du?</div><div class=\"kurss-example\">Was tut er? — Vad gör han?</div><div class=\"kurss-example\">Was tut sie? — Vad gör hon?</div><div class=\"kurss-example\">Was tun sie? — Vad gör de?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negation med ”nicht”</h4>\n              <p>Om negationen ”nicht” syftar på verbet står den på tyska vanligtvis efter verbet.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Jag spelar inte.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul frågar inte.</div><div class=\"kurss-example\">Er kommt nicht. — Han kommer inte.</div><div class=\"kurss-example\">Sie singen nicht. — De sjunger inte.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Meningar från lektion 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Spelar du?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nej, jag spelar inte, jag arbetar.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul frågar inte, han arbetar.</div><div class=\"kurss-example\">Arbeitest du? — Arbetar du?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nej, jag arbetar inte, jag sjunger.</div><div class=\"kurss-example\">Was tut Paul? — Vad gör Paul?</div><div class=\"kurss-example\">Er spielt. — Han spelar.</div><div class=\"kurss-example\">Was tut Marie? — Vad gör Marie?</div><div class=\"kurss-example\">Sie singt. — Hon sjunger.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul spelar, men Marie sjunger.</div><div class=\"kurss-example\">Singt ihr? — Sjunger ni?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nej, vi sjunger inte, vi arbetar.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Vad gör Paul och Marie?</div><div class=\"kurss-example\">Sie fragen. — De frågar.</div><div class=\"kurss-example\">Sie antworten nicht. — De svarar inte.</div><div class=\"kurss-example\">Wer arbeitet? — Vem arbetar?</div><div class=\"kurss-example\">Wir arbeiten. — Vi arbetar.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Vi räknar och ritar.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — De kommer, frågar, svarar, arbetar, spelar, sjunger och går.</div></div>\n            </section>",
  "kurssLesson1": "            <h3>Lektion 1</h3>\n            <p class=\"kurss-lesson-intro\">Första lektionen: verb i presens, ord, uttal, grammatik och översättning.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verb i presens</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verb och deras böjning i presens.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — komma</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>jag kommer</span><span>du</span><strong>kommst</strong><span>du kommer</span><span>er / sie</span><strong>kommt</strong><span>han / hon kommer</span><span>wir</span><strong>kommen</strong><span>vi kommer</span><span>ihr</span><strong>kommt</strong><span>ni kommer</span><span>sie / Sie</span><strong>kommen</strong><span>de / Ni kommer</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — gå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>jag går</span><span>du</span><strong>gehst</strong><span>du går</span><span>er / sie</span><strong>geht</strong><span>han / hon går</span><span>wir</span><strong>gehen</strong><span>vi går</span><span>ihr</span><strong>geht</strong><span>ni går</span><span>sie / Sie</span><strong>gehen</strong><span>de / Ni går</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — stå</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>jag står</span><span>du</span><strong>stehst</strong><span>du står</span><span>er / sie</span><strong>steht</strong><span>han / hon står</span><span>wir</span><strong>stehen</strong><span>vi står</span><span>ihr</span><strong>steht</strong><span>ni står</span><span>sie / Sie</span><strong>stehen</strong><span>de / Ni står</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — sjunga</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>jag sjunger</span><span>du</span><strong>singst</strong><span>du sjunger</span><span>er / sie</span><strong>singt</strong><span>han / hon sjunger</span><span>wir</span><strong>singen</strong><span>vi sjunger</span><span>ihr</span><strong>singt</strong><span>ni sjunger</span><span>sie / Sie</span><strong>singen</strong><span>de / Ni sjunger</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Exempel</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Ordens ungefärliga uttal anges inom parentes med svenska bokstäver.<br>Detta gäller även i de följande lektionerna.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) — vi</div><div class=\"kurss-example\">I ordet ”wir” uttalas bokstaven i långt.</div><div class=\"kurss-example\">kommen (kommen) — komma</div><div class=\"kurss-example\">gehen (ghe-en) — gå</div><div class=\"kurss-example\">stehen (schte-en) — stå</div><div class=\"kurss-example\">singen (zingen) — sjunga</div><div class=\"kurss-example\">du (do) kommst — du kommer</div><div class=\"kurss-example\">er (er) kommt — han kommer</div><div class=\"kurss-example\">sie (zi) kommt — hon kommer</div><div class=\"kurss-example\">wer (ver) — vem?</div><div class=\"kurss-example\">ja (ja) — ja</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ordens korrekta uttal, skrivet med svenska bokstäver, anges i lektionerna.</div><div class=\"kurss-example\">Wir (vir) — vi. I wir uttalas i alltid långt.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitiv</h4><div class=\"lesson1-grammar-note\">Verbets grundform. Infinitiven slutar oftast på -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Presensändelser</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Ta bort <span class=\"lesson1-ending-accent\">-en</span> från verbets grundform och lägg till ändelsen.</strong></p><p>Exempel: kommen → komm + ändelse</p><div class=\"lesson1-ending-process\" aria-label=\"Så bildas presensändelserna\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>grundform</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>ta bort <span class=\"lesson1-ending-accent\">-en</span></strong><span>stammen blir kvar</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>stam</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>lägg till ändelsen</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Exempel</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Frågesatser</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>I en tysk frågesats flyttas verbet oftast till första plats.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På svenska:<br>Du kommer.<br>Kommer du?</div><div class=\"kurss-example\">På tyska:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — du kommer<br>kommst du? — kommer du?</div><div class=\"kurss-example\">er singt — han sjunger<br>singt er? — sjunger han?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Skillnad mellan personer</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — han kommer</div><div class=\"kurss-example\">sie kommt — hon kommer</div><div class=\"kurss-example\">sie kommen — de kommer</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 1 – övningskort\">\n                    <span class=\"lesson1-training-progress\">Lektion 1 · Översätt: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Kommer du?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson2": "            <h3>Lektion 2</h3>\n            <p class=\"kurss-lesson-intro\">Andra lektionen: dialoger, ord, uttal, grammatik och översättning.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — leka; spela</div>\n                  <div class=\"kurss-example\">nein — nej</div>\n                  <div class=\"kurss-example\">nicht — inte</div>\n                  <div class=\"kurss-example\">arbeiten — arbeta</div>\n                  <div class=\"kurss-example\">fragen — fråga</div>\n                  <div class=\"kurss-example\">was tut er? — vad gör han?</div>\n                  <div class=\"kurss-example\">was tun sie? — vad gör de?</div>\n                  <div class=\"kurss-example\">aber — men</div>\n                  <div class=\"kurss-example\">antworten — svara</div>\n                  <div class=\"kurss-example\">rechnen — räkna</div>\n                  <div class=\"kurss-example\">zeichnen — rita</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I orden ich, nicht, rechnen, zeichnen uttalas ljudet ch mjukt, ungefär som tj-ljudet i svenska ord som tjugo och kjol.</div><div class=\"kurss-example\">I orden arbeiten, zeichnen uttalas diftongen ei ungefär som svenskt aj i ordet haj.</div><div class=\"kurss-example\">Konsonantförbindelsen sp uttalas som schp: spielen (schpilen).</div><div class=\"kurss-example\">I verbet tun uttalas u långt i alla personer.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Ändelser med e</h4>\n                  <div class=\"lesson1-grammar-note\">Om verbstammen slutar på t, d eller chn, står ett e före ändelserna -st och -t vid böjningen.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Frågeord</h4>\n                  <div class=\"lesson1-grammar-note\">I frågesatser som börjar med ett frågeord, till exempel: vad? vem? vilken? varför? hur? osv., står verbet direkt efter frågeordet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Vad gör du?</div><div class=\"kurss-example\">Was tut er? — Vad gör han?</div><div class=\"kurss-example\">Was tut sie? — Vad gör hon?</div><div class=\"kurss-example\">Was tun sie? — Vad gör de?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negation med nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Om negationen nicht gäller verbet, står den efter verbet.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — Han kommer inte.</div><div class=\"kurss-example\">Sie singen nicht. — De sjunger inte.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 2 – översättningskort\">\n                    <span class=\"lesson1-training-progress\">Lektion 2 · Översätt: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Vem frågar?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson3": "            <h3>Lektion 3</h3>\n            <p class=\"kurss-lesson-intro\">Tredje lektionen: dialoger, ord, uttal, grammatik och översättning.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — vem</div><div class=\"kurss-example\">was — vad</div><div class=\"kurss-example\">hier — här</div><div class=\"kurss-example\">dort — där</div><div class=\"kurss-example\">der Tisch — bordet</div><div class=\"kurss-example\">ein Tisch — ett bord</div><div class=\"kurss-example\">die Bank — bänken</div><div class=\"kurss-example\">eine Bank — en bänk</div><div class=\"kurss-example\">liegen — ligga</div><div class=\"kurss-example\">liegt hier ein Buch? — finns / ligger det en bok här?</div><div class=\"kurss-example\">das Buch — boken</div><div class=\"kurss-example\">ein Buch — en bok</div><div class=\"kurss-example\">hängen — hänga</div><div class=\"kurss-example\">das Bild — bilden</div><div class=\"kurss-example\">ein Bild — en bild</div><div class=\"kurss-example\">die Tafel — tavlan</div><div class=\"kurss-example\">eine Tafel — en tavla</div><div class=\"kurss-example\">wie — hurdan, hurdant</div><div class=\"kurss-example\">ist — är</div><div class=\"kurss-example\">dick — tjock</div><div class=\"kurss-example\">das Heft — skrivhäftet</div><div class=\"kurss-example\">ein Heft — ett skrivhäfte</div><div class=\"kurss-example\">dünn — tunn</div><div class=\"kurss-example\">niedrig — låg</div><div class=\"kurss-example\">hoch — hög</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Det långa i-ljudet skrivs på tyska ie: liegen (lighen), hier (hir), wie (vi).</div><div class=\"kurss-example\">ck är ett dubbelt k: dick (dikk).</div><div class=\"kurss-example\">I adjektiv och adverb låter ändelsen -ig som ett lätt -ich: niedrig (nidrich).</div><div class=\"kurss-example\">Om ändelsen -ig följs av e, alltså -ige, uttalas g som ett tydligt g: niedrige (nidrighe) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subjekt</h4><div class=\"lesson1-grammar-note\">Subjektet i en tysk sats svarar på frågan wer? / was? och står i nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Med wer? frågar man efter personer.</div><div class=\"kurss-example\">Med was? frågar man efter saker.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Artiklar</h4><div class=\"lesson1-grammar-note\">På tyska har substantiven 3 genus: maskulinum, femininum och neutrum. Framför substantivet står oftast ett litet ord som kallas artikel. Detta ord översätts inte separat.</div><h5 class=\"lesson2-subtitle\">Bestämd artikel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maskulinum — der</div><div class=\"kurss-example\">femininum — die</div><div class=\"kurss-example\">neutrum — das</div><div class=\"kurss-example\">I plural är den bestämda artikeln die för alla tre genus.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Obestämd artikel</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">maskulinum — ein</div><div class=\"kurss-example\">femininum — eine</div><div class=\"kurss-example\">neutrum — ein</div><div class=\"kurss-example\">Den obestämda artikeln har ingen pluralform.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Egennamn</h4><div class=\"lesson1-grammar-note\">Framför egennamn används ingen artikel.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbets plats</h4><div class=\"lesson1-grammar-note\">I ett påstående står verbet på andra plats.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tyska säger man om föremål som står upprätt att de står:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Om föremål som ligger vågrätt säger man att de ligger:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Föremål kan också hänga:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 3 – översättningskort\"><span class=\"lesson1-training-progress\">Lektion 3 · Översätt: 1 / 22</span><span class=\"lesson1-training-text\">Räknar du?</span></button><p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p></div></div></details>",
  "kurssLesson4": "            <h3>Lektion 4</h3>\n            <p class=\"kurss-lesson-intro\">Ackusativ, nehmen, hinlegen, hinausgehen och adjektiv.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nemen) — ta</div><div class=\"kurss-example\">er nimmt (nimt) — han tar</div><div class=\"kurss-example\">der Federhalter (der federhalter) — pennskaftet</div><div class=\"kurss-example\">einen Federhalter — ett pennskaft</div><div class=\"kurss-example\">zeigen — visa</div><div class=\"kurss-example\">schwarz (schvarts) — svart</div><div class=\"kurss-example\">weiß (vajs) — vit</div><div class=\"kurss-example\">die Feder (di feder) — pennan</div><div class=\"kurss-example\">eine Feder — en penna</div><div class=\"kurss-example\">spitz (schpits) — spetsig</div><div class=\"kurss-example\">hinlegen — lägga ner</div><div class=\"kurss-example\">legt hin — lägger ner</div><div class=\"kurss-example\">das Mädchen (määtchen) — flickan</div><div class=\"kurss-example\">das Messer — kniven</div><div class=\"kurss-example\">ein Messer — en kniv</div><div class=\"kurss-example\">scharf — vass</div><div class=\"kurss-example\">stumpf (schtompf) — slö, trubbig</div><div class=\"kurss-example\">dann — sedan</div><div class=\"kurss-example\">hinaus — ut</div><div class=\"kurss-example\">hinausgehen — gå ut</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Ändelserna -en, -er, -el är obetonade, därför hörs e i dessa ändelser bara svagt: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">h kan på tyska vara antingen ett ljud eller ett längdtecken för den föregående vokalen.</div><div class=\"kurss-example\">Om h är ett längdtecken uttalas det inte som ett ljud: nehmen (nemen).</div><div class=\"kurss-example\">Om vokalen följs av bara en konsonant uttalas vokalen långt: die (di) Feder (feder), den (den).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Ackusativ</h4><div class=\"lesson1-grammar-note\">I femininum och neutrum är ackusativ likadan som nominativ. Bara maskulinum ändras.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronomen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — maskulinum</div><div class=\"kurss-example\">sie — femininum</div><div class=\"kurss-example\">es — neutrum</div><div class=\"kurss-example\">i plural — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Delbara verb</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjektiv</h4><div class=\"lesson1-grammar-note\">Om adjektivet är predikativ i satsen böjs det varken i genus eller i numerus.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negation med nicht</h4><div class=\"lesson1-grammar-note\">Om nicht negerar ett adjektiv, står det före det negerade ordet.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Substantiv med ändelsen -chen och -lein är neutrum: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 4 – översättningskort\"><span class=\"lesson1-training-progress\">Lektion 4 · Översätt: 1 / 16</span><span class=\"lesson1-training-text\">Flickan tar ett pennskaft.</span></button><p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p></div></div></details>",
  "kurssLesson5": "\n    <h3>Lektion 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, ackusativ, sitzen, fragen och ändelsen -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zitsen) — sitta</div>\n        <div class=\"kurss-example\">fragen (fragen) — fråga</div>\n        <div class=\"kurss-example\">der Lehrer (der lerer) — läraren</div>\n        <div class=\"kurss-example\">gut (got) — bra</div>\n        <div class=\"kurss-example\">wen (ven) — vem</div>\n        <div class=\"kurss-example\">loben — berömma</div>\n        <div class=\"kurss-example\">der Schüler (schyler) — eleven</div>\n        <div class=\"kurss-example\">klein — liten</div>\n        <div class=\"kurss-example\">groß (grås) — stor</div>\n        <div class=\"kurss-example\">die Lehrerin — lärarinnan</div>\n        <div class=\"kurss-example\">die Schülerin — skolflickan, den kvinnliga eleven</div>\n        <div class=\"kurss-example\">schlecht (schlecht) — dåligt</div>\n        <div class=\"kurss-example\">tadeln — klandra</div>\n        <div class=\"kurss-example\">oder (åder) — eller</div>\n        <div class=\"kurss-example\">das Kind (khint) — barnet</div>\n        <div class=\"kurss-example\">artig (aartich) — snäll, väluppfostrad</div>\n        <div class=\"kurss-example\">die Mutter — modern, mamman</div>\n        <div class=\"kurss-example\">lieben (liben) — älska</div>\n        <div class=\"kurss-example\">der Vater (fater) — fadern, pappan</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz är ett fördubblat z och uttalas som tyskt z, alltså ts: sitzen (zitsen).</div>\n        <div class=\"kurss-example\">v uttalas i tyska ord som f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß kallas eszett och uttalas som svenskt s: groß (grås), weiß (vajs).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativ och ackusativ</h4><div class=\"lesson1-grammar-note\">På svenska svarar både subjekt och direkt objekt på frågorna vem? och vad?, men tyskan skiljer här mellan nominativ och ackusativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">På tyska är frågan i nominativ wer? för personer och was? för saker.</div><div class=\"kurss-example\">I ackusativ är frågan wen? för personer och was? för saker.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Artiklarnas förändring i ackusativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + ackusativ</h4><div class=\"lesson1-grammar-note\">Verbet fragen styr ackusativ på tyska.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Ändelsen -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Många feminina ord bildas med ändelsen -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Verbets plats</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">I ett påstående står verbet på andra plats.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 5 – översättningskort\"><span class=\"lesson1-training-progress\">Lektion 5 · Översätt: 1 / 16</span><span class=\"lesson1-training-text\">Vem älskar pappan?</span></button><p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson6": "\n    <h3>Lektion 6</h3>\n    <p class=\"kurss-lesson-intro\">Räkneord, plural, omljud och substantivens pluralformer.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — ligger, finns, är</div><div class=\"kurss-example\">der Bleistift (blajschtift) — blyertspennan</div><div class=\"kurss-example\">einige (ajnighe) — några</div><div class=\"kurss-example\">hinlegen — lägga ner</div><div class=\"kurss-example\">legt hin — lägger ner</div><div class=\"kurss-example\">wieder (vider) — igen</div><div class=\"kurss-example\">aufmachen — öppna</div><div class=\"kurss-example\">er macht auf — han öppnar</div><div class=\"kurss-example\">anspitzen (anschpitsen) — vässa</div><div class=\"kurss-example\">er spitzt an — han vässar</div><div class=\"kurss-example\">sich setzen — sätta sig</div><div class=\"kurss-example\">setzt sich — sätter sig</div><div class=\"kurss-example\">der Schlüssel (schlyssel) — nyckeln</div><div class=\"kurss-example\">das Fenster (fenster) — fönstret</div><div class=\"kurss-example\">die Tafel (di tafel) — tavlan</div><div class=\"kurss-example\">der Garten — trädgården</div><div class=\"kurss-example\">der Löffel — skeden</div><div class=\"kurss-example\">zählen (tselen) — räkna</div><div class=\"kurss-example\">die Nadel — nålen</div><div class=\"kurss-example\">was ist das — vad är det?</div><div class=\"kurss-example\">der Hammer — hammaren</div><div class=\"kurss-example\">die Hämmer — hamrarna</div><div class=\"kurss-example\">der Deckel (der deckel) — locket</div><div class=\"kurss-example\">der Teller — tallriken</div><div class=\"kurss-example\">der Wagen — vagnen, kärran</div><div class=\"kurss-example\">der Schlitten — släden, kälken</div><div class=\"kurss-example\">das Ding — saken</div><div class=\"kurss-example\">die Dinge — sakerna</div><div class=\"kurss-example\">wie sind die Dinge? — hurdana är sakerna?</div><div class=\"kurss-example\">voll (fåll) — full</div><div class=\"kurss-example\">leer (ler) — tom</div><div class=\"kurss-example\">schwer (schver) — tung, svår</div><div class=\"kurss-example\">leicht — lätt</div><div class=\"kurss-example\">der Eimer — hinken</div><div class=\"kurss-example\">wieviel (vifil) — hur många</div><div class=\"kurss-example\">wieviel Nadeln — hur många nålar</div><div class=\"kurss-example\">hier (hir) — här</div><div class=\"kurss-example\">dort — där</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä är omljudet av vokalen a och uttalas som ett kort eller långt svenskt ä.</div><div class=\"kurss-example\">Exempel: das Mädchen (määtchen), die Bänke (di bänke), der Vater (der fater), die Väter (di fäter).</div><div class=\"kurss-example\">ü är omljudet av vokalen u. När man uttalar det ska läpparna rundas kraftigt, och med rundade läppar försöker man säga i, vilket ger ett ljud som liknar svenskt y.</div><div class=\"kurss-example\">Exempel: fünf, der Schlüssel (schlyssel).</div><div class=\"kurss-example\">ö uttalas med rundade läppar medan man försöker säga e, ungefär som svenskt ö: der Löffel.</div><div class=\"kurss-example\">En dubbelskriven vokal betecknar en lång vokal: leer (ler).</div><div class=\"kurss-example\">Diftongen eu uttalas som oj: neun (nojn).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Grammatik och förklaringar</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Det betonade prefixet i ett sammansatt verb skiljs i presens från verbet och står i slutet av satsen.</div><div class=\"kurss-example\">Exempel: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Räkneordet en/ett har former för alla tre genus när det används med ett substantiv: maskulinum ein, femininum eine, neutrum ein.</div><div class=\"kurss-example\">Exempel: ein Schüler — en elev; eine Schülerin — en kvinnlig elev; ein Kind — ett barn.</div><div class=\"kurss-example\">Räkneord: eins, zwei, drei, vier (fir), fünf, sechs (zecks), sieben (ziben), acht, neun (nojn), zehn (tsen).</div><div class=\"kurss-example\">Kopulan har på tyska en singular- och en pluralform: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Precis som på svenska, där man säger det är både om en och om flera saker, används på tyska en enda form av det pekande pronomenet: das.</div><div class=\"kurss-example\">Exempel: det är en hammare — das ist ein Hammer; det är en nål — das ist eine Nadel; det är hammare — das sind Hämmer; det är nålar — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — vagn och der Schlitten — släde används på tyska både i singular och i plural.</div><div class=\"kurss-example\">Maskulina och neutrala substantiv på -er, -el, -en får ofta ingen ändelse i plural.</div><div class=\"kurss-example\">Exempel: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Feminina substantiv på -el, -er får -n i plural.</div><div class=\"kurss-example\">Exempel: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Undantag: die Mutter (mor) — die Mütter (mödrar); die Tochter (dotter) — die Töchter (döttrar).</div><div class=\"kurss-example\">Den obestämda artikeln har ingen pluralform: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">I ett påstående står predikatsverbet på andra plats: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Översätt</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 6 – översättningskort\"><span class=\"lesson1-training-progress\">Lektion 6 · Översätt: 1 / 21</span><span class=\"lesson1-training-text\">Paul tar en blyertspenna och ritar.</span></button><p class=\"lesson1-training-hint\">Klicka på kortet för att se den tyska översättningen. Efter svaret visar nästa klick nästa kort.</p></div></div>\n    </details>\n  ",
  "kurssLesson7": "            <h3>Lektion 7</h3>\n            <p class=\"kurss-lesson-intro\">Sjunde lektionen: imperativ, tilltalsform och plural.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoger / meningar</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Ord</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — sjunga</div><div class=\"kurss-example\">singe — sjung</div><div class=\"kurss-example\">singt — sjung (till flera)</div><div class=\"kurss-example\">singen Sie — sjung (artigt tilltal)</div><div class=\"kurss-example\">das Lied (das lit) — sången, visan</div><div class=\"kurss-example\">Sie — Ni (artigt tilltal)</div><div class=\"kurss-example\">zählen — räkna</div><div class=\"kurss-example\">das Fräulein (frojlajn) — fröken</div><div class=\"kurss-example\">der Müller — mjölnaren</div><div class=\"kurss-example\">öffnen — öppna</div><div class=\"kurss-example\">das Fenster (fenster) — fönstret</div><div class=\"kurss-example\">alle — alla</div><div class=\"kurss-example\">der Spiegel (schpighel) — spegeln</div><div class=\"kurss-example\">der Lappen — trasan</div><div class=\"kurss-example\">der Spaten — spaden</div><div class=\"kurss-example\">der Besen — kvasten</div><div class=\"kurss-example\">die Schaufel — skyffeln</div><div class=\"kurss-example\">die Schüssel — skålen</div><div class=\"kurss-example\">das Zimmer — rummet</div><div class=\"kurss-example\">das Ufer (ofer) — stranden</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Uttal</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">sp i början av ett ord eller en stavelse uttalas som schp: der Spiegel (der schpighel).</div><div class=\"kurss-example\">sch uttalas ungefär som svenskt sj-ljud: die Schaufel (di schaufel), die Schüssel (di schyssel).</div><div class=\"kurss-example\">Diftongen äu uttalas som svenskt oj: das Fräulein (das frojlajn).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Grammatik</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Imperativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativ i andra person singular motsvarar verbets form i andra person singular utan personändelsen -st, med tillägg av ändelsen -e.</div><div class=\"kurss-example\">Exempel: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Mycket ofta används ändelsen -e inte, om imperativformen är enstavig: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativ i plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativformen i andra person plural är likadan som andra person plural i presens, men används utan pronomen.</div><div class=\"kurss-example\">Exempel: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Tilltalsform med Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Den artiga tilltalsformen med ”Ni” motsvarar tredje person plural. Pronomenet Sie skrivs med stor bokstav och står efter verbet.</div><div class=\"kurss-example\">Exempel: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">För att underlätta uttalet skjuts ett e in mellan stam och ändelse i verbet öffnen i andra och tredje person singular och i andra person plural: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Övning</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lektion 7 – övningskort\"><span class=\"lesson1-training-progress\">Lektion 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — fråga</span></button><p class=\"lesson1-training-hint\">Tryck på kortet för att se imperativformerna.</p></div></div></details>"
};

